568	import net.officefloor.hq.app.rate.RateRepository;
569	import net.officefloor.hq.app.sheet.SheetRepository;
570	import net.officefloor.plugin.variable.Out;
571	import net.officefloor.plugin.variable.Val;
572	
573	/**
574	 * Takes the person's statement on the sheet's today: records their due-total, binds each of their counting claims
575	 * to the figure it has now, and unbinds the rest. A claim's figure is its settled due when it has one, else the
576	 * figure its last statement bound it to, else its amount times its person's grade's rate in force on the claim's
577	 * date (rounded half to even; none without a rate). The due-total is the counting claims' figures added up; n/a
578	 * (null) when the grade has no rate today and no counting claim keeps a settled or bound figure.
579	 */
580	public class TakeStatement {
581	    public void take(@Val Person person, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
582	            StatementRepository statements, Out<Statement> taken) {
583	        String sheetId = person.getSheetId();
584	        LocalDate today = sheets.today(sheetId);
585	        List<Claim> mine = claims.listOf(sheetId, person.getId());
586	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
587	        boolean kept = false;
588	        int counted = 0;
589	        for (Claim c : mine) {
590	            if (!c.getStatus().counts()) {
591	                claims.bind(c.getId(), false, null);
592	                continue;
593	            }
594	            counted++;
595	            kept |= c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null);
596	            BigDecimal figure = figure(c, person, rates);
597	            if (figure != null) {
598	                sum = sum.add(figure);
599	            }
600	            claims.bind(c.getId(), true, figure);
601	        }
602	        BigDecimal dueTotal = kept || rates.find(sheetId, person.getGrade(), today) != null ? sum : null;
603	        statements.insert(sheetId, person.getId(), dueTotal, today);
604	        person.setStatements(new Statements(person.getStatements().count() + 1, dueTotal, today));
605	        taken.set(new Statement(dueTotal, counted));
606	    }
607	
608	    private static BigDecimal figure(Claim claim, Person person, RateRepository rates) {
609	        if (claim.getSettledDue() != null) {
610	            return claim.getSettledDue();
611	        }
612	        if (claim.isStated()) {
613	            return claim.getStatedDue();
614	        }
615	        BigDecimal rate = rates.find(claim.getSheetId(), person.getGrade(), claim.getDate());
616	        return rate == null ? null
617	                : claim.getAmount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
618	    }
619	}
