745	/** The periods of each sheet, none overlapping another on its sheet. */
746	@Repository
747	public class PeriodRepository {
748	
749	    static final String NAME_TAKEN = "That period name is already in use on this sheet";
750	
751	    private static final RowMapper<Period> ROW = (rs, n) -> new Period(rs.getLong("id"), rs.getString("sheet_id"),
752	            rs.getString("name"), rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate(),
753	            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"));
754	
755	    private static final String COLUMNS = "id, sheet_id, name, from_date, to_date, closed, closed_total";
756	
757	    private final JdbcTemplate jdbc;
758	
759	    public PeriodRepository(JdbcTemplate jdbc) {
760	        this.jdbc = jdbc;
761	    }
762	
763	    /** The sheet's periods, by from-date. */
764	    public List<Period> list(String sheetId) {
765	        return jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ?"
766	                + " ORDER BY from_date, id", ROW, sheetId);
767	    }
768	
769	    /** Whether a period on the sheet has this name, ignoring case and surrounding spaces. */
770	    public boolean nameTaken(String sheetId, String name) {
771	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))",
772	                Integer.class, sheetId, name);
773	        return n != null && n > 0;
774	    }
775	
776	    /** Whether a period on the sheet shares a day with the dates from..to (inclusive). */
777	    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
778	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
779	                Integer.class, sheetId, Date.valueOf(to), Date.valueOf(from));
780	        return n != null && n > 0;
781	    }
782	
783	    public Period insert(String sheetId, String name, LocalDate from, LocalDate to) {
784	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
785	        jdbc.update(con -> {
786	            PreparedStatement ps = con.prepareStatement(
787	                    "INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)", new String[] { "id" });
788	            ps.setString(1, sheetId);
789	            ps.setString(2, name);
790	            ps.setDate(3, Date.valueOf(from));
791	            ps.setDate(4, Date.valueOf(to));
792	            return ps;
793	        }, keys);
794	        return new Period(keys.getKey().longValue(), sheetId, name, from, to, false, null);
795	    }
796	
797	    public Period find(String sheetId, long id) {
798	        return jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND id = ?", ROW, sheetId, id)
799	                .stream().findFirst().orElse(null);
800	    }
801	
802	    /** Whether the date falls inside a closed period of the sheet. */
803	    public boolean closedOn(String sheetId, LocalDate date) {
804	        Integer n = jdbc.queryForObject(
805	                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND closed AND from_date <= ? AND to_date >= ?",
806	                Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
807	        return n != null && n > 0;
