904	import java.io.IOException;
905	import java.io.UncheckedIOException;
906	import java.nio.charset.StandardCharsets;
907	import java.nio.file.Files;
908	import java.nio.file.Path;
909	import java.nio.file.StandardOpenOption;
910	import org.springframework.beans.factory.annotation.Value;
911	import org.springframework.stereotype.Service;
912	
913	/**
914	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
915	 * so tests can assert side-effects by reading that file — the second test-assertion channel
916	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
917	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
918	 *
919	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
920	 * SYNC) so a test reads the record immediately.
921	 */
922	@Service
923	public class Audit {
924	
925	    private final Path file;
926	
927	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
928	        this.file = Path.of(path);
929	    }
930	
931	    /** Append one audit record. Tests assert the exact line(s) in the file. */
932	    public synchronized void record(String entry) {
933	        try {
934	            Path parent = file.toAbsolutePath().getParent();
935	            if (parent != null) {
936	                Files.createDirectories(parent);
937	            }
938	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
939	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
940	        } catch (IOException e) {
941	            throw new UncheckedIOException(e);
942	        }
943	    }
944	
945	    /** Remove the audit file. */
946	    public synchronized void clear() {
947	        try {
948	            Files.deleteIfExists(file);
949	        } catch (IOException e) {
950	            throw new UncheckedIOException(e);
951	        }
952	    }
953	}
